solution_code.javascript:
function leastInterval(tasks, n) {
    const freq = {};
    for (const t of tasks) freq[t] = (freq[t] || 0) + 1;
    const maxFreq = Math.max(...Object.values(freq));
    const maxFreqCount = Object.values(freq).filter(v => v === maxFreq).length;
    const frame = (maxFreq - 1) * (n + 1) + maxFreqCount;
    return Math.max(frame, tasks.length);
}

