class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = None

def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    # Trie oluştur
    root = TrieNode()
    for word in words:
        node = root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.word = word

    rows, cols = len(board), len(board[0])
    result = []

    def backtrack(r, c, parent):
        letter = board[r][c]
        node = parent.children.get(letter)
        if not node:
            return
        if node.word:
            result.append(node.word)
            node.word = None  # tekrar ekleme
        board[r][c] = '#'  # visited
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                backtrack(nr, nc, node)
        board[r][c] = letter  # geri al
        # Pruning: cocugu kalmamissa sil
        if not node.children:
            del parent.children[letter]

    for r in range(rows):
        for c in range(cols):
            backtrack(r, c, root)
    return result

