function findWords(board, words) {
    const root = { children: {}, word: null };
    for (const word of words) {
        let node = root;
        for (const char of word) {
            if (!node.children[char]) node.children[char] = { children: {}, word: null };
            node = node.children[char];
        }
        node.word = word;
    }
    const rows = board.length, cols = board[0].length;
    const result = [];
    function backtrack(r, c, parent) {
        const letter = board[r][c];
        const node = parent.children[letter];
        if (!node) return;
        if (node.word) {
            result.push(node.word);
            node.word = null;
        }
        board[r][c] = '#';
        for (const [dr, dc] of [[0,1],[0,-1],[1,0],[-1,0]]) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== '#') {
                backtrack(nr, nc, node);
            }
        }
        board[r][c] = letter;
        if (Object.keys(node.children).length === 0) delete parent.children[letter];
    }
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            backtrack(r, c, root);
    return result;
}
